def sector(a):
    return tuple(1 if x > 0 else 0 for x in a)

for a in [(1, 1, 1, 1, 1), (2, 1, 1, 1, 3), (1, 1, 1, 1, -2), (1, 1, 1, 1, 0), (0, 1, 1, 0, 1), (0, 2, 1, -1, 1)]:
    print("F%s  is in sector %s" % (a, sector(a)))

